#!/usr/bin/env python3"""Comprehensive fix for bin/agent/prompts.py:1. Add _serialize_element + _write_prompts_xml (CDATA-based XML writer)2. Update _prompt_node to use CDATA for <value>3. Add update_base_prompts_from_xml function4. Add --update-base CLI flag"""from pathlib import Pathtarget = Path("bin/agent/prompts.py")source = target.read_text(encoding="utf-8")# --- 1. Replace _prompt_node to use CDATA ---old_prompt_node = '''def _prompt_node(name: str, value: str, *, base_path: str | None = None) -> ET.Element:    prompt = ET.Element("prompt")    name_el = ET.SubElement(prompt, "name")    name_el.text = name    if base_path:        base_path_el = ET.SubElement(prompt, "base_path")        base_path_el.text = base_path    value_el = ET.SubElement(prompt, "value")    value_el.text = "\\n" + value.strip("\\n") + "\\n"    return prompt'''new_prompt_node = '''def _prompt_node(name: str, value: str, *, base_path: str | None = None) -> ET.Element:    prompt = ET.Element("prompt")    name_el = ET.SubElement(prompt, "name")    name_el.text = name    if base_path:        base_path_el = ET.SubElement(prompt, "base_path")        base_path_el.text = base_path    value_el = ET.SubElement(prompt, "value")    value_el.text = "\\n" + value.strip("\\n") + "\\n"    return promptdef _serialize_element(elem: ET.Element, indent: str = "") -> str:    """Serialize an Element to XML string with CDATA for <value> elements."""    parts: list[str] = []    tag = elem.tag    attrs = ""    for k, v in elem.attrib.items():        attrs += f' {k}="{v}"'    children = list(elem)    has_children = len(children) > 0    if tag == "value" and elem.text:        # Use CDATA to avoid entity escaping        cdata_content = elem.text        parts.append(f"{indent}<{tag}{attrs}><![CDATA[{cdata_content}]]></{tag}>")        return "".join(parts)    if not has_children and (elem.text is None or not elem.text.strip()):        parts.append(f"{indent}<{tag}{attrs} />")    elif not has_children:        text = elem.text or ""        parts.append(f"{indent}<{tag}{attrs}>{text}</{tag}>")    else:        parts.append(f"{indent}<{tag}{attrs}>")        for child in children:            parts.append("\\n")            parts.append(_serialize_element(child, indent + "  "))        parts.append(f"\\n{indent}</{tag}>")    return "".join(parts)def _write_prompts_xml(tree: ET.ElementTree, target: Path) -> None:    """Write the prompts XML tree to *target* using CDATA for <value> elements."""    root = tree.getroot()    xml_str = '<?xml version="1.0" encoding="UTF-8"?>\\n'    xml_str += _serialize_element(root)    xml_str += "\\n"    target.write_text(xml_str, encoding="utf-8")'''if old_prompt_node in source:    source = source.replace(old_prompt_node, new_prompt_node, 1)    print("OK: _prompt_node + _serialize_element + _write_prompts_xml added")else:    print("SKIP: _prompt_node not found (may already be patched)")# --- 2. Add update_base_prompts_from_xml before read_prompts_config ---if "def update_base_prompts_from_xml" not in source:    func_code = '''def update_base_prompts_from_xml(path: str | Path | None = None) -> Path:    """Read XML <system> values and write them back as hardcoded defaults here."""    target = Path(path).expanduser().resolve() if path else prompts_config_path()    if not target.exists():        raise FileNotFoundError(f"prompts_config.xml not found at {target}")    tree = _read_tree(target)    root = tree.getroot()    system, _project = _ensure_sections(root)    xml_prompts = _read_prompt_section(system)    if not xml_prompts:        return target    this_file = Path(__file__).resolve()    src = this_file.read_text(encoding="utf-8")    lines: list[str] = ["DEFAULT_SYSTEM_PROMPTS: Dict[str, str] = {"]    seen: set[str] = set()    for key in DEFAULT_SYSTEM_PROMPTS:        seen.add(key)        value = xml_prompts.get(key, DEFAULT_SYSTEM_PROMPTS[key])        lines.append(f"    {key!r}: {value!r},")    for key, value in xml_prompts.items():        if key in seen:            continue        lines.append(f"    {key!r}: {value!r},")    lines.append("}")    new_block = "\\n".join(lines)    pattern = re.compile(        r"DEFAULT_SYSTEM_PROMPTS:\\s*Dict\\[str,\\s*str\\]\\s*=\\s*\\{.*?\\n\\}",        re.DOTALL,    )    if not pattern.search(src):        raise RuntimeError("Could not locate DEFAULT_SYSTEM_PROMPTS dict in prompts.py source")    updated = pattern.sub(new_block, src, count=1)    this_file.write_text(updated, encoding="utf-8")    return target'''    anchor = "def read_prompts_config(path: str | Path | None = None) -> Dict[str, Dict[str, str]]:"    if anchor in source:        source = source.replace(anchor, func_code + anchor, 1)        print("OK: update_base_prompts_from_xml added")    else:        print("ERROR: read_prompts_config anchor not found")else:    print("SKIP: update_base_prompts_from_xml already exists")# --- 3. Add --update-base CLI flag ---if '"--update-base"' not in source:    cli_anchor = '    if "--reset-system" in args:\n        print(reset_system_prompts_to_defaults())\n        return 0'    cli_replacement = '    if "--update-base" in args:\n        print(update_base_prompts_from_xml())\n        return 0\n    if "--reset-system" in args:\n        print(reset_system_prompts_to_defaults())\n        return 0'    if cli_anchor in source:        source = source.replace(cli_anchor, cli_replacement, 1)        print("OK: --update-base CLI flag added")    else:        print("ERROR: CLI anchor not found")else:    print("SKIP: --update-base already exists")target.write_text(source, encoding="utf-8")print("Done")